def compute(vars):
    operating_leases = vars["v1"]
    total_contractual_obligations = vars["v2"]

    if total_contractual_obligations == 0:
        return None

    percentage_ratio = operating_leases / total_contractual_obligations

    return {
        "value": percentage_ratio,
        "trace": {
            "operating_leases": operating_leases,
            "total_contractual_obligations": total_contractual_obligations,
            "percentage_ratio": percentage_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
